    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range [1, 9], it's highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: Reward placements that leave room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward fitting the next item
        } else {
            score += 25.0; // Penalize blocking the next item
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only prioritize if we have many bins open already (high fragmentation) 
        // or if fitting_bins_count is low (no good existing options).
        score += 40.0;
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // Existing bin: Reward using bins that are already "less empty" to consolidate
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Global Fragmentation Control: If mean_residual is high, we are under-utilizing space.
    // Penalize placements that increase the mean_residual significantly.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // 5. Final constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

