pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Core objective: Minimize post_residual (Best Fit), but penalize creating "dead space" 
    // that cannot accommodate typical future items.

    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items as f64 + 1.0);

    // 1. Best-Fit Penalty: Penalize small residuals that are too small for common items (e.g., < 10)
    // but not exactly zero (which is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global State Balancing: If we have many open bins, penalize opening a new one.
    // If we have very few, be more aggressive about keeping bins packed tightly.
    if is_new_bin {
        score += 40.0; // Base resistance to opening new bins
        score -= (open_bins_count as f64 * 0.5); // More bins open = slightly easier to open another
    } else {
        // Reward bins that keep the global mean residual low.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 4. Scarcity Logic: If this is the last chance for the current item, 
    // reduce the penalty for a poor fit to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Dynamic Horizon: As we near the end of the stream, prioritize closing bins
    // by being more lenient on remaining space (don't leave empty holes).
    if progress > 0.9 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best Fit Decreasing logic: Favor bins that result in small post_residual (Best Fit)
    // We already have post_residual in the score.

    // 2. Lookahead Penalty: If the next item is large, avoid creating a bin that is too tight for it.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
        score += 45.0 * (1.0 - progress);
    }

    // 3. Global Efficiency: Penalize opening new bins early in the stream, 
    // but allow it if it leads to a very tight fit (post_residual < 5).
    if is_new_bin {
        if post_residual < 5 {
            score -= 10.0;
        } else {
            score += 30.0 * (1.0 - progress);
        }
    }

    // 4. Pressure Valve: If we have many open bins, penalize new bins heavily.
    if is_new_bin && open_bins_count > 5 {
        score += (open_bins_count as f64) * 15.0;
    }

    // 5. Residual Balancing: Penalize bins that deviate significantly from the mean_residual
    // to encourage uniform fill across all active bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Urgency: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // 7. Small Item Aggregation: If the item is small and we are near the end, 
    // prioritize packing into existing bins to close them out.
    if item_size < 25 && progress > 0.8 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize Best-Fit (lower post_residual)
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but not zero,
    // it often prevents larger future items from fitting.
    // We heavily penalize small residues that are below the expected item size (approx 40-50).
    if post > 0.0 && post < 45.0 {
        score += (45.0 - post).powf(1.5);
    }

    // Lookahead logic: if next_item_size is large, avoid leaving a residual
    // that is just slightly smaller than the next item.
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.5;
        }
    }

    // Dynamic adjustment based on stream progress:
    // Early in the stream, be conservative (prefer full bins).
    // Near the end, be aggressive (avoid opening new bins).
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        // This is the "New Bin" candidate call.
        // Penalize opening a new bin heavily unless we are at the very start
        // or the current mean_residual is very low (bins are effectively full).
        score += 100.0 * (1.0 - progress) + (mean_residual * 0.5);
    } else {
        // Existing bin candidate:
        // Favor bins that align with the global mean to keep packing density uniform.
        score += (post - mean_residual).abs() * 0.2;
    }

    // Penalize opening too many bins relative to progress
    score += (open_bins_count as f64 * (1.0 - progress)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We add a non-linear penalty for creating "fragmented" space (small remaining residuals)
    // Fragmented space is defined as residuals < 15, which are hard to fill.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5)
    } else {
        0.0
    };

    // Reward utilizing bins that are already "tight" to keep open_bins_count low
    let bin_tightness_reward = (bin_capacity - bin_residual) as f64 * 0.5;

    // Lookahead logic: if next_item_size is large, avoid leaving a tiny post_residual
    // that cannot accommodate the next item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Dynamic threshold: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones (penalize opening new bins).
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Coupling: Use mean_residual to dampen the penalty of opening new bins
    // if the existing bins are already very full (mean_residual is low).
    let global_fullness_adjustment = (mean_residual / bin_capacity as f64) * 10.0;

    let mut score = post 
        + fragmentation_penalty 
        + lookahead_penalty 
        + new_bin_penalty 
        - bin_tightness_reward 
        - global_fullness_adjustment;

    // If this is the only fitting bin, heavily prioritize it to prevent 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero,
    // as they create "unfillable" gaps. 
    // We favor residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    let harmonic_penalty = if post_residual > 0 && post_residual < 10 {
        25.0
    } else if post_residual % 20 == 0 {
        -10.0
    } else {
        0.0
    };

    // 2. Lookahead Coupling: If the next item can fit in the current post_residual, 
    // prioritize this bin significantly to create a "perfect pair".
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -30.0 - (post_residual - next_item_size) as f64 * 0.5
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // If it doesn't fit, penalize the residual based on how much "wasted" space is created.
        (next_item_size - post_residual) as f64 * 0.2
    } else {
        0.0
    };

    // 3. Density Control: If this is the last fitting bin, prioritize it to avoid
    // opening a new bin unnecessarily (Best Fit behavior).
    let desperation_factor = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    // 4. New Bin Threshold: If we are considering a new bin, only pick it if the
    // mean residual of existing bins is already very tight.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if mean_residual > 15.0 {
            score += 5.0; // Discourage opening new bins if current ones have space
        } else {
            score += 60.0; // Heavily penalize opening new bins if we have efficient ones
        }
    }

    score += harmonic_penalty + lookahead_bonus + desperation_factor;

    // 5. Progress Normalization: As the stream progresses, tighten constraints.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bins heavily early on, but allow them as the stream progresses
    // to prevent fragmentation of early, highly-packed bins.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Base penalty for opening a new bin, decays as we reach the end of the stream
        score += 45.0 * (1.0 - progress).powf(0.5);

        // If we are at the very end, we are less picky about opening new bins
        if progress > 0.95 { score -= 20.0; }
    } else {
        // Favor bins that result in a "tight" fit (Best Fit logic)
        // Non-linear penalty for leaving large gaps
        score += (post_residual as f64).powf(1.5) * 0.1;

        // Lookahead: If next_item_size is large, avoid leaving a small post_residual
        // that would make the next item impossible to fit.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 2.5;
            }
        }

        // If this is the last bin that can fit the current item, prioritize it
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Adjust for global state: if we have too many open bins, penalize keeping more open
    score += (open_bins_count as f64).powf(1.2) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual_ratio = post / bin_capacity as f64;

    // Base score: prioritize tightest fit (Best-Fit principle).
    let mut score = post;

    // Penalty for creating 'fragmented' bins:
    // If post_residual is small but > 0, it creates a dead zone (e.g., < 10).
    // This is most dangerous in the late stages of the stream.
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 + progress);
    }

    // Lookahead interaction: if next_item_size is large, favor larger post_residuals
    // to accommodate future items, especially if currently few bins are open.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64 - post) / bin_capacity as f64;
        if lookahead_pressure > 0.0 {
            score += 20.0 * lookahead_pressure * (1.0 - progress);
        }
    }

    // New bin logic:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only open a new bin if the existing bins are too tight to accommodate 
    // the current item or if the average residual is already very low.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Mandatory new bin
        } else {
            // Heavily penalize opening a new bin if an existing bin can fit the item
            // unless the mean_residual is already very small (bins are nearly full).
            score = 50.0 + (100.0 - mean_residual) * (1.0 - progress);
        }
    } else {
        // Favor bins that align with the global mean residual to keep bin states uniform.
        let deviation = (post - mean_residual).abs();
        score += 5.0 * deviation;
    }

    score
}
